"Осей 4: две через середины сторон и две по диагоналям.": "There are 4 axes: two through the midpoints of the sides and two along the diagonals.",
"Урок 5. Числовые и буквенные выражения. Преобразование": "Lesson 5. Numerical and letter expressions. Transformation",
"Сколько натуральных решений у неравенства 99 < x < 106?": "How many natural number solutions does the inequality 99 < x < 106 have?",
