"распределительное свойство: (3 + 4) · 5 = 3 · 5 + 4 · 5": "distributive property: (3 + 4) · 5 = 3 · 5 + 4 · 5",
"V = 10 · 6 · 5 = 300 (дм³). 1 дм³ = 1 л, значит, 300 л.": "V = 10 · 6 · 5 = 300 (dm³). 1 dm³ = 1 l, so 300 l.",
"предмет, развёртка которого — прямоугольник и два круга": "an object whose net is a rectangle and two circles",
"Меньшее число пишем слева, большее справа: 60 < n < 150.": "We write the smaller number on the left, the larger on the right: 60 < n < 150.",
"Лишнее данное в задаче не нужно для ответа на её вопрос.": "The extra data in a problem is not needed to answer its question.",
"объём больше 500 см³: рёбра 10, 10, 10 см (V = 1000 см³)": "volume greater than 500 cm³: edges 10, 10, 10 cm (V = 1000 cm³)",
