"Потраченные деньги надо прибавить: x = 700 + 300 = 1 000.": "The money spent must be added: x = 700 + 300 = 1 000.",
"Потраченные деньги надо прибавить: x = 700 + 300 = 1 000.": "The money spent must be added: x = 700 + 300 = 1 000.",
"Числа между 24 и 30: 25, 26, 27, 28, 29. Наибольшее — 29.": "The numbers between 24 and 30: 25, 26, 27, 28, 29. The largest is 29.",
"тупоугольный: углы 110°, 40° и 30° (есть угол больше 90°)": "obtuse-angled: angles 110°, 40° and 30° (there is an angle greater than 90°)",
