"5 = 10 : 2. Поэтому 48 · 5 = 48 · 10 : 2 = 480 : 2 = 240.": "5 = 10 : 2. So 48 · 5 = 48 · 10 : 2 = 480 : 2 = 240.",
"В решения не входит граница 17. Верно: { 13, 14, 15, 16 }.": "The boundary 17 is not among the solutions. Correct: { 13, 14, 15, 16 }.",
"Выражение a − 3 · b значит: из a вычли произведение 3 и b.": "The expression a − 3 · b means: the product of 3 and b was subtracted from a.",
"Стороны треугольника: 13, 13 и 13 дм. Чему равен периметр?": "The sides of a triangle: 13, 13 and 13 dm. What is the perimeter?",
"Если два угла треугольника 90° и 40°, то третий равен 50°.": "If two angles of a triangle are 90° and 40°, then the third is 50°.",
"Автобус быстрее на 15 км/ч. За 2 ч разрыв: 15 · 2 = 30 км.": "The bus is faster by 15 km/h. In 2 h the gap is 15 · 2 = 30 km.",
"Посмотри на буквы: одинаковые можно сложить, разные нельзя.": "Look at the letters: the same ones can be added, different ones cannot.",
"Доли одинаковые, поэтому больше та дробь, где долей больше.": "The parts are the same, so the fraction with more parts is greater.",
"задача про покупку: цена 150 тг, 4 штуки (150 · 4 = 600 тг)": "a shopping problem: price 150 tenge, 4 items (150 · 4 = 600 tenge)",
"В 6 часов стрелки часов образуют угол 180°. Какой это угол?": "At 6 o'clock the hands of a clock form an angle of 180°. What kind of angle is it?",
"проволоки 36 см: каркас 2 × 3 × 4 см ((2 + 3 + 4) · 4 = 36)": "wire 36 cm: frame 2 × 3 × 4 cm ((2 + 3 + 4) · 4 = 36)",
"Множество решений неравенства 3 < x < 8 — { 3, 4, 5, 6, 7 }.": "The set of solutions of the inequality 3 < x < 8 is { 3, 4, 5, 6, 7 }.",
"Если было x тенге и потратили 300, осталось 700, то x = 400.": "If there were x tenge and 300 was spent, 700 is left, then x = 400.",
"1) 48 − 15 = 33 (м.) — у Али. 2) 48 + 33 = 81 (м.) — вместе.": "1) 48 − 15 = 33 (stamps) — Ali has. 2) 48 + 33 = 81 (stamps) — together.",
"числа и действия: 3 400 · 20 (умножение многозначного числа)": "numbers and operations: 3 400 · 20 (multiplying a multi-digit number)",
"числа и действия: 3 400 · 20 (умножение многозначного числа)": "numbers and operations: 3 400 · 20 (multiplying a multi-digit number)",
"На ферме b овец, а коз в 3 раза больше. Сколько коз на ферме?": "A farm has b sheep, and there are 3 times as many goats. How many goats are on the farm?",
"Блокноты по 90 тг заплатили 720 тг. Сколько блокнотов купили?": "Notepads cost 90 tenge each and 720 tenge was paid. How many notepads were bought?",
